/// Tolerance on the binned outgoing energy, relative. NJOY's own MF=6 rows
/// through this port reproduce the ACE file to 5.3e-11; feeding our `calcem`
/// instead leaves ~2.6e-5, which is the 7th-digit difference between an
/// in-memory law and one round-tripped through an ENDF tape — so the gate is
/// set to catch an algorithm change, not that rounding.
const E_TOL: f64 = 2.0e-4;
/// Tolerance on the cosines, absolute (same reasoning; measured 7.1e-4).
const MU_TOL: f64 = 3.0e-3;

#[test]
fn acesix_reproduces_njoy2016_ace_thermal_bins() {
    let Some(path) = reference_endf_or_skip("tsl-crystalline-graphite.endf", "acesix-golden")
    else {
        return;
    };
    let tape = Tape::read_file(&path).expect("graphite TSL tape");
    let mat = *tape.materials().first().expect("a material");
    let ii = parse_mf7_at_temperature(&tape, mat, Some(600.0))
        .expect("MF=7 parse")
        .incoherent_inelastic
        .expect("graphite has incoherent inelastic");
    // The THERMR deck's dimensions: 8 cosine bins, emax 4.0 eV, tol 0.05.
    let table = compute_iform0(&ii, 1.0, 8, 4.0, 0.05).expect("calcem iform=0");

    let (mut worst_e, mut worst_mu) = ((0.0f64, 0.0f64), (0.0f64, 0.0f64));
    let mut compared = 0usize;
    for &(e_in, njoy_bins) in NJOY_ACE_BINS {
        let rec = table
            .records
            .iter()
            .find(|r| (r.e_in_ev - e_in).abs() / e_in < 1.0e-6)
            .unwrap_or_else(|| panic!("no calcem record at E = {e_in:e} eV"));
        // `iwt = 1` — constant weights, matching the ACER card above.
        let bins = acesix_equiprobable(&normalized_rows(&rec.rows), 64, BinWeights::Constant);
        assert_eq!(
            bins.len(),
            njoy_bins.len(),
            "bin count at E = {e_in:e} eV: {} against NJOY's {}",
            bins.len(),
            njoy_bins.len()
        );
        for (ours, &(e_n, mu_n)) in bins.iter().zip(njoy_bins) {
            compared += 1;
            let rel = (ours.e_out_ev - e_n).abs() / e_n.max(1.0e-30);
            if rel > worst_e.0 {
                worst_e = (rel, e_in);
            }
            for (c, &m) in mu_n.iter().enumerate() {
                let d = (ours.cosines[c] - m).abs();
                if d > worst_mu.0 {
                    worst_mu = (d, e_in);
                }
            }
        }
    }
    println!(
        "  vs NJOY2016 ACE: {compared} bins; worst E_out {:.3e} relative at {:.3e} eV, \
         worst cosine {:.3e} at {:.3e} eV",
        worst_e.0, worst_e.1, worst_mu.0, worst_mu.1
    );
    assert!(
        worst_e.0 < E_TOL,
        "binned outgoing energy is {:.3e} relative from NJOY2016's own ACE file at \
         E = {:.3e} eV. Given identical MF=6 input this port reproduces that file to \
         5.3e-11, so a failure here is an algorithm change in acesix, not rounding.",
        worst_e.0,
        worst_e.1
    );
    assert!(
        worst_mu.0 < MU_TOL,
        "binned cosine is {:.3e} from NJOY2016's own ACE file at E = {:.3e} eV \
         (measured 7.1e-4 through our calcem, 6.0e-12 through NJOY's own MF=6)",
        worst_mu.0,
        worst_mu.1
    );
}
